// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.voice.wakewordimport timber.log.Timberimport android.content.Contextimport com.roshan.persona.voice.capture.AudioCapturePipelineimport com.roshan.persona.voice.capture.CircularAudioBufferimport com.roshan.persona.voice.capture.VoiceActivityDetector/** * NOUS — Wake Word Detector (v2: 3-Tier DSP-first). * * Listens for the "Hey NOUS" wake word (or a user-trained custom phrase) and * fires [onWakeWordDetected] when a confirmed detection occurs. This is the * always-on entry point for the entire voice stack — when nothing is talking, * only this detector is consuming power. * * ## v2 3-Tier Architecture (review fix #4) * * ``` * Tier 1: Hardware DSP (Always-On, < 0.5 %/hour) *   ├── SoundTriggerManager (Qualcomm Hexagon / MediaTek APU) *   ├── CPU stays asleep, no wakelock *   └── Wake word detected → CPU wakes *           ↓ * Tier 2: Software Confirmation (TFLite, runs on CPU) *   ├── OpenWakeWord (4 MB TFLite model) *   ├── MFCC 2nd-stage confirmation (10× false-positive reduction) *   └── Speaker pre-check (optional — owner-voice-only mode) *           ↓ (confirmed) * Tier 3: Full Pipeline Activation *   ├── Start STT engine *   ├── Start Speaker Recognition *   ├── Start SER (Speech Emotion Recognition) *   └── Start Audio Capture (full pipeline) * ``` * * Why 3 tiers: hardware DSP alone has ~3 % false positives (acceptable for * always-on but not for "open the garage door" use cases); software-only is * too battery-hungry (8-12 %/hour) for always-on. Combining them gives DSP * battery + software precision. * * ## Battery budgets (§16) * * | Mode                       | Battery/Hour | * |----------------------------|--------------| * | Hardware DSP (Tier 1 only) | < 0.5 %      | * | Software fallback (always) | ~3 %         | * | Deep sleep                 | < 1 %        | * * ## Testability * * Both [Hardware] and [Software] implementations are reachable through the * sealed interface; the [Factory] picks the best one for the device at * runtime. Tests substitute implementations via DI. * * @see <a href="docs/strategy/module-5-strategy-v2.md">§4 Wake Word Detection (Always-On) — v2: DSP-Level</a> */sealed interface WakeWordDetector {    /**     * Begin listening for the wake word. Idempotent — calling twice is a no-op.     *     * After this call returns, [onWakeWordDetected] (passed at construction)     * will eventually fire when a confirmed detection occurs.     */    fun start()    /** Stop listening. Idempotent. Releases DSP / CPU resources. */    fun stop()    /** Whether this detector is currently the always-on tier (vs software). */    val isHardwareAccelerated: Boolean    /** Whether the detector is actively listening right now. */    val isRunning: Boolean    /** Release all native resources. Idempotent. */    fun release()    // ──────────────────────────────────────────────────────────────────────    /**     * A confirmed wake-word detection event.     *     * `audioTrigger` may be `null` when the hardware DSP detected the phrase     * but didn't capture audio (rare on most devices; common on Qualcomm     * Hexagon in deep sleep). Software confirmation always populates it.     *     * @param confidence    0.0 – 1.0 confidence from the confirming stage.     * @param speakerMatch  true if the speaker pre-check passed (or was     *                       skipped because no owner print is enrolled).     * @param audioTrigger  2-second audio lead-in from the circular buffer,     *                       starting just before the wake word was spoken.     *                       Suitable for STT/continuation. May be null when     *                       hardware DSP didn't capture audio.     */    data class WakeWordEvent(        val confidence: Float,        val speakerMatch: Boolean,        val audioTrigger: ShortArray?,        val timestampMs: Long = System.currentTimeMillis(),    )    // ──────────────────────────────────────────────────────────────────────    /**     * Configuration for the wake word detector.     *     * @param keyphrase           the phrase to listen for ("Hey NOUS" by default).     * @param hardwareModelPath   path to the SoundTrigger-compatible model     *                             (UDK model file). Required for hardware tier.     * @param softwareModelPath   path to OpenWakeWord TFLite model (~4 MB).     * @param wakeWordThreshold   0.0–1.0; confidence above this triggers Tier 2.     * @param mfccConfirmEnabled  run 2nd-stage MFCC confirmation (10× false-pos     *                             reduction). Disable for low-end devices.     * @param speakerPreCheck     require enrolled owner voice print match.     * @param vadAggressiveness   0–3; VAD pre-filter aggressiveness.     */    data class Config(        val keyphrase: String = DEFAULT_KEYPHRASE,        val hardwareModelPath: String? = null,        val softwareModelPath: String = "openwakeword/hey_nous.tflite",        val wakeWordThreshold: Float = DEFAULT_THRESHOLD,        val mfccConfirmEnabled: Boolean = true,        val speakerPreCheck: Boolean = false,        val vadAggressiveness: Int = 2,    )    // ──────────────────────────────────────────────────────────────────────    /**     * Factory — picks the best [WakeWordDetector] for this device.     *     * Order of preference:     *  1. [Hardware] — if [android.media.soundtrigger.SoundTriggerManager] is     *     available and reports a non-null module.     *  2. [Software] — always-available fallback.     *     * The factory also wires the shared [CircularAudioBuffer] from     * [AudioCapturePipeline] so the wake-word event includes a 2 s lead-in.     */    class Factory {        fun create(            context: Context,            config: Config,            circularBuffer: CircularAudioBuffer,            onWakeWordDetected: (WakeWordEvent) -> Unit,        ): WakeWordDetector {            val hardware = HardwareWakeWordDetector.tryCreate(                context = context,                config = config,                circularBuffer = circularBuffer,                onWakeWordDetected = onWakeWordDetected,            )            if (hardware != null) {                Timber.tag(TAG).i("Hardware wake word detector available — using SoundTriggerManager.")                return hardware            }            Timber.tag(TAG).w("Hardware wake word unavailable — falling back to software (OpenWakeWord).")            return SoftwareWakeWordDetector(                context = context,                config = config,                circularBuffer = circularBuffer,                onWakeWordDetected = onWakeWordDetected,                audioSource = com.roshan.persona.voice.capture.AndroidAudioSource(context),                captureDispatcher = kotlinx.coroutines.Dispatchers.Default,            )        }        private companion object {            private const val TAG = "WakeWordDetector"        }    }    // ──────────────────────────────────────────────────────────────────────    companion object {        /** Default wake phrase. */        const val DEFAULT_KEYPHRASE = "Hey NOUS"        /** OpenWakeWord confidence threshold (§4 §OpenWakeWord Integration). */        const val DEFAULT_THRESHOLD = 0.7f        /** Circular buffer duration in seconds — matches AudioCapturePipeline. */        const val CIRCULAR_BUFFER_SECONDS = AudioCapturePipeline.CIRCULAR_BUFFER_SECONDS    }}
